        char c = 'A';

        System.out.println(c);               // A   文字として
        System.out.println((int) c);         // 65  数として
        System.out.println((char) (c + 1));  // B   1つ次の文字

        long  big  = 10000000000L;   // L を付ける
        float rate = 1.5f;           // f を付ける
        System.out.println(big);
        System.out.println(rate);
    }
}

